SELECT

FROM finance_transaction t
LEFT JOIN finance_category c ON c.id = t.category_id AND c.deleted = 0 AND c.user_id = t.user_id
LEFT JOIN finance_account a ON a.id = t.account_id AND a.deleted = 0 AND a.user_id = t.user_id
LEFT JOIN finance_account fa ON fa.id = t.from_account_id AND fa.deleted = 0 AND fa.user_id = t.user_id
LEFT JOIN finance_account ta ON ta.id = t.to_account_id AND ta.deleted = 0 AND ta.user_id = t.user_id

    t.deleted = 0
    AND t.user_id = #{userId}

        AND t.txn_type = #{dto.txnType}


        AND t.status = #{dto.status}


        AND (t.account_id = #{dto.accountId}
          OR t.from_account_id = #{dto.accountId}
          OR t.to_account_id = #{dto.accountId})


        AND t.category_id = #{dto.categoryId}


        AND t.txn_date  >=  #{dto.txnDateStart}


        AND t.txn_date  <=  #{dto.txnDateEnd}


        AND t.note LIKE CONCAT('%', #{dto.note}, '%')


ORDER BY t.txn_date DESC, t.id DESC

SELECT COALESCE(SUM(t.amount), 0)
FROM finance_transaction t
WHERE t.deleted = 0
  AND t.user_id = #{userId}

    AND t.txn_type = #{txnType}


    AND t.status = #{status}


    AND t.txn_date  >=  #{startDate}


    AND t.txn_date  <=  #{endDate}

SELECT COUNT(1)
FROM finance_transaction t
WHERE t.deleted = 0
  AND t.user_id = #{userId}
  AND (t.account_id = #{accountId}
    OR t.from_account_id = #{accountId}
    OR t.to_account_id = #{accountId})

SELECT COUNT(1)
FROM finance_transaction t
WHERE t.deleted = 0
  AND t.user_id = #{userId}
  AND t.category_id = #{categoryId}
